import {createRequire} from 'node:module';
import {dirname,join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {cpSync,copyFileSync,mkdtempSync,mkdirSync,readFileSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {createStatusClient} from './status.js';
export {createStatusClient};
import {obtainShell as invokeShell} from './shell.js';
export const obtainShell=(settings,options={})=>invokeShell(settings,{...options,call:options.call??createClient()});
const sdkRequire=createRequire(import.meta.url);
export const sdkVersion=JSON.parse(readFileSync(new URL('../package.json',import.meta.url),'utf8')).version;
let koffi;
let productRoot;

/** Use the SDK-owned native dependency for existing direct Windows bindings. */
export function loadKoffi() {
  if(!koffi) {
    // Windows pins loaded .node files. Keep them outside the removable package.
    const root=mkdtempSync(join(tmpdir(),'finshield-sdk-koffi-'));
    for(const name of ['koffi',`@koromix/koffi-${process.platform}-${process.arch}`])
      cpSync(dirname(sdkRequire.resolve(name)),join(root,'node_modules',name),{recursive:true});
    koffi=createRequire(join(root,'package.json'))('koffi');
  }
  return koffi;
}

/** The SDK carries the product library; operation targets remain explicit. */
export function createClient({libraryRoot,require}={}) {
  if(!libraryRoot){
    if(!productRoot){
      const root=mkdtempSync(join(tmpdir(),`finshield-sdk-product-${sdkVersion}-`));
      mkdirSync(join(root,'bin'));
      copyFileSync(fileURLToPath(new URL('../bin/finsafe_native.dll',import.meta.url)),join(root,'bin','finsafe_native.dll'));
      productRoot=root;
    }
    libraryRoot=productRoot;
  }
  const call=createNativeAdapter(libraryRoot,'finsafe_native.dll','finsafe',{require});
  call.buildInfo=async()=>{
    const info=await call({module:'execution',request:{action:'build_info'}});
    return {...info,version:sdkVersion,nativeVersion:info.version};
  };
  call.libraryPath=join(libraryRoot,'bin','finsafe_native.dll');
  call.sdkRoot=fileURLToPath(new URL('../',import.meta.url));
  return call;
}

// Extracted from DSH. Native handles and singleton state stay in the product.
export function createNativeAdapter(root,filename,prefix,{require}={}) {
  const koffi=require?require('koffi'):loadKoffi();
  const library=koffi.load(join(root,'bin',filename));
  const invoke=library.func(`void* ${prefix}_call(str input)`);
  const free=library.func(`void ${prefix}_free(void* value)`);
  let callbackType;
  const call=request=>new Promise((resolve,reject)=>{
    const input=JSON.stringify(request);
    if(Buffer.byteLength(input)>16384) return reject(Error('Native request exceeds 16 KiB'));
    invoke.async(input,(error,pointer)=>{
      if(error) return reject(error);
      try {
        const result=JSON.parse(koffi.decode(pointer,'char',-1));
        if(!result.ok) throw Error(result.error);
        resolve(result.value);
      } catch(error) {reject(error);} finally {free(pointer);}
    });
  });
  call.watchMain=(request,onExit)=>{
    callbackType??=koffi.proto('void FinSafeProcessExitCallback(void)');
    const callback=koffi.register(onExit,koffi.pointer(callbackType));
    const watch=library.func(`void* ${prefix}_watch_process(str input, void* callback)`);
    let pointer,observer;
    try {
      pointer=watch(JSON.stringify(request),callback);
      const result=JSON.parse(koffi.decode(pointer,'char',-1));
      if(!result.ok)throw Error(result.error);
      observer=result.value.observer;
    }catch(error){koffi.unregister(callback);throw error;}
    finally{if(pointer)free(pointer);}
    return async()=>{
      await call({module:'execution',request:{action:'unwatch_process',observer}});
      koffi.unregister(callback);
    };
  };
  return call;
}
